/* Kalinaw Bay Resort — fictional sample data. Regenerated by "Reset sample data". */
window.R = window.R || {};

(function () {
  // seeded random so every reset gives the same believable resort
  let seed = 20261111;
  const rnd = () => { seed = (seed * 1664525 + 1013904223) % 4294967296; return seed / 4294967296; };
  const pick = a => a[Math.floor(rnd() * a.length)];
  const int = (a, b) => a + Math.floor(rnd() * (b - a + 1));

  const iso = d => { const z = new Date(d); z.setMinutes(z.getMinutes() - z.getTimezoneOffset()); return z.toISOString().slice(0, 10); };
  const addDays = (s, n) => { const d = new Date(s + 'T12:00:00'); d.setDate(d.getDate() + n); return iso(d); };
  const TODAY = iso(new Date());
  R.util = { iso, addDays, TODAY };

  R.makeData = function () {
    seed = 20261111;

    const roomTypes = [
      { id: 'GDN', name: 'Garden Room', base: 189, cap: 2, size: '28 m²', bed: 'Queen', view: 'Tropical garden' },
      { id: 'OCV', name: 'Ocean View Room', base: 259, cap: 3, size: '34 m²', bed: 'King', view: 'Partial ocean' },
      { id: 'FAM', name: 'Family Suite', base: 329, cap: 5, size: '55 m²', bed: 'King + 2 singles', view: 'Garden & pool' },
      { id: 'PVL', name: 'Pool Villa', base: 620, cap: 4, size: '90 m²', bed: 'King', view: 'Private plunge pool' },
      { id: 'BVL', name: 'Beachfront Villa', base: 449, cap: 4, size: '70 m²', bed: 'King + sofa bed', view: 'Direct beach access' }
    ];

    const zones = [
      { id: 'garden', name: 'Garden Wing', type: 'GDN', prefix: '1', count: 12 },
      { id: 'ocean', name: 'Ocean Wing', type: 'OCV', prefix: '2', count: 12 },
      { id: 'family', name: 'Family Suites', type: 'FAM', prefix: '3', count: 6 },
      { id: 'pool', name: 'Pool Villas', type: 'PVL', prefix: 'P', count: 6 },
      { id: 'beach', name: 'Beachfront Villas', type: 'BVL', prefix: 'V', count: 10 }
    ];

    const rooms = [];
    zones.forEach(z => {
      for (let i = 1; i <= z.count; i++) {
        const no = /\d/.test(z.prefix) ? z.prefix + String(i).padStart(2, '0') : z.prefix + i;
        rooms.push({ no, type: z.type, zone: z.id, hk: 'inspected', attendant: null, note: '' });
      }
    });

    const first = ['Olivia','Liam','Mia','Noah','Isla','Jack','Amelia','Oliver','Grace','Leo','Chloe','Lucas','Ava','Ethan','Sofia','Hugo','Aisha','Kenji','Priya','Mateo','Hana','Diego','Zara','Sam','Lena','Arjun','Maya','Tom','Ella','Ravi','Nina','Ben','Sakura','Omar','Lucy','Felix','Ivy','Marco','Yuki','Ana'];
    const last = ['Nguyen','Smith','Santos','Brown','Reyes','Wilson','Tanaka','Patel','Garcia','Taylor','Kim','Martin','Cruz','Lee','Rossi','Walker','Chen','Silva','Murphy','Kaur','Dubois','Novak','Haddad','Ito','Kowalski','Fischer','Lopez','Ong','Hughes','Bautista'];
    const countries = ['Australia','Australia','Australia','New Zealand','Singapore','Japan','USA','UK','Germany','Philippines','South Korea','Canada'];
    const tags = ['', '', '', 'VIP', 'Repeat guest', 'Honeymoon', 'Birthday', 'Allergy: nuts', 'Late arrival', 'Vegetarian'];

    const guests = [];
    for (let i = 0; i < 120; i++) {
      const f = pick(first), l = pick(last);
      guests.push({
        id: 'G' + (1000 + i), name: f + ' ' + l,
        email: (f + '.' + l).toLowerCase() + '@example.com',
        phone: '+61 4' + int(10, 99) + ' ' + int(100, 999) + ' ' + int(100, 999),
        country: pick(countries), tag: pick(tags), stays: int(1, 4) === 4 ? int(2, 6) : 1
      });
    }

    const channels = ['Direct website', 'Direct website', 'Booking.com', 'Booking.com', 'Expedia', 'Airbnb', 'Phone / email', 'Walk-in'];
    const typeOf = no => rooms.find(r => r.no === no).type;
    const priceOf = t => roomTypes.find(x => x.id === t).base;

    const reservations = [];
    let resNo = 4100, gi = 0;
    const nextGuest = () => guests[gi++ % guests.length];

    rooms.forEach(room => {
      let d = addDays(TODAY, -int(8, 14));
      const end = addDays(TODAY, 30);
      while (d < end) {
        d = addDays(d, int(0, 2) + (rnd() < 0.35 ? int(2, 6) : 0)); // gap between stays
        if (d >= end) break;
        const nights = int(1, 6);
        const g = nextGuest();
        const rate = Math.round(priceOf(room.type) * (0.9 + rnd() * 0.3));
        reservations.push({
          id: 'KB-' + (resNo++), guestId: g.id, type: room.type, room: room.no,
          arrive: d, nights, adults: int(1, Math.min(2, roomTypes.find(x => x.id === room.type).cap)),
          children: room.type === 'FAM' ? int(1, 3) : (rnd() < 0.15 ? 1 : 0),
          channel: pick(channels), rate, status: 'booked', notes: g.tag, folio: [], paid: 0,
          eta: pick(['12:00', '14:00', '15:00', '16:00', '18:00', '21:00'])
        });
        d = addDays(d, nights);
      }
    });

    // derive status relative to today
    reservations.forEach(r => {
      const dep = addDays(r.arrive, r.nights);
      if (dep === TODAY && rnd() < 0.75) r.status = 'inhouse'; // leaving today, not checked out yet
      else if (dep <= TODAY) r.status = 'checkedout';
      else if (r.arrive < TODAY) r.status = 'inhouse';
      else if (r.arrive === TODAY && rnd() < 0.3) r.status = 'inhouse'; // early check-ins already done
      if (r.status !== 'booked') {
        const n = r.status === 'checkedout' ? r.nights : Math.max(1, Math.round((new Date(TODAY) - new Date(r.arrive)) / 864e5));
        for (let i = 0; i < n; i++) r.folio.push({ date: addDays(r.arrive, i), desc: 'Room night', dept: 'Rooms', amount: r.rate });
        if (rnd() < 0.6) r.folio.push({ date: r.arrive, desc: 'Lagoon Restaurant dinner', dept: 'Food & beverage', amount: int(60, 220) });
        if (rnd() < 0.3) r.folio.push({ date: r.arrive, desc: 'Coral Spa massage', dept: 'Spa', amount: 165 });
        if (r.status === 'checkedout') r.paid = r.folio.reduce((s, x) => s + x.amount, 0);
        else r.paid = r.channel === 'Booking.com' || r.channel === 'Expedia' ? r.rate * r.nights : Math.round(r.rate * 0.3);
      }
      if (r.status === 'booked' && rnd() < 0.08) r.status = 'cancelled';
    });

    // some upcoming bookings have no room assigned yet — front desk assigns them
    reservations.filter(r => r.status === 'booked' && r.arrive > TODAY).forEach(r => { if (r.arrive <= addDays(TODAY, 7) && rnd() < 0.15) r.room = null; });

    // housekeeping state follows occupancy
    rooms.forEach(room => {
      const ih = reservations.find(r => r.room === room.no && r.status === 'inhouse');
      const leftToday = reservations.find(r => r.room === room.no && r.status === 'checkedout' && addDays(r.arrive, r.nights) === TODAY);
      if (ih) room.hk = rnd() < 0.35 ? 'dirty' : 'clean';
      else if (leftToday) room.hk = rnd() < 0.7 ? 'dirty' : 'clean';
      else room.hk = rnd() < 0.8 ? 'inspected' : 'clean';
    });
    const ooo = rooms.find(r => r.no === '207');
    ooo.hk = 'ooo'; ooo.note = 'Air-con unit replaced — awaiting part';
    // free 207 from any in-house guest so the story is consistent
    for (let i = reservations.length - 1; i >= 0; i--) {
      const r = reservations[i];
      if (r.room === '207' && r.status !== 'checkedout' && r.arrive <= addDays(TODAY, 3)) reservations.splice(i, 1);
    }

    const staff = [
      { id: 'S1', name: 'Marisol Reyes', dept: 'Management', role: 'General manager' },
      { id: 'S2', name: 'Daniel Okafor', dept: 'Front office', role: 'Front office manager' },
      { id: 'S3', name: 'Kirra Thompson', dept: 'Front office', role: 'Receptionist' },
      { id: 'S4', name: 'Josh Bennett', dept: 'Front office', role: 'Night auditor' },
      { id: 'S5', name: 'Lani Kealoha', dept: 'Housekeeping', role: 'Executive housekeeper' },
      { id: 'S6', name: 'Rosa Dimaano', dept: 'Housekeeping', role: 'Room attendant' },
      { id: 'S7', name: 'Ahmed Rahimi', dept: 'Housekeeping', role: 'Room attendant' },
      { id: 'S8', name: 'Grace Lim', dept: 'Housekeeping', role: 'Room attendant' },
      { id: 'S9', name: 'Tevita Fonua', dept: 'Maintenance', role: 'Maintenance lead' },
      { id: 'S10', name: 'Paolo Ferri', dept: 'Food & beverage', role: 'Head chef' },
      { id: 'S11', name: 'Jade Wu', dept: 'Food & beverage', role: 'Restaurant supervisor' },
      { id: 'S12', name: 'Noa Levi', dept: 'Food & beverage', role: 'Bartender' },
      { id: 'S13', name: 'Mele Tupou', dept: 'Spa & activities', role: 'Spa therapist' },
      { id: 'S14', name: 'Ricky Hale', dept: 'Spa & activities', role: 'Dive & tour guide' }
    ];
    const attendants = ['S6', 'S7', 'S8'];
    rooms.forEach((r, i) => { if (r.hk === 'dirty' || r.hk === 'clean') r.attendant = attendants[i % 3]; });

    const shiftOpts = ['06:00–14:00', '14:00–22:00', '22:00–06:00', 'Off'];
    const roster = {};
    staff.forEach(s => {
      roster[s.id] = [];
      for (let i = 0; i < 7; i++) roster[s.id].push(s.role === 'Night auditor' ? (i % 6 === 5 ? 'Off' : '22:00–06:00') : (rnd() < 0.2 ? 'Off' : pick(shiftOpts.slice(0, 2))));
    });

    const activities = [
      { id: 'A1', name: 'Coral Spa — 60 min massage', dept: 'Spa', price: 165, times: ['10:00', '12:00', '14:00', '16:00'], cap: 2 },
      { id: 'A2', name: 'Reef snorkel trip', dept: 'Tours', price: 95, times: ['08:30', '13:30'], cap: 12 },
      { id: 'A3', name: 'Sunset catamaran cruise', dept: 'Tours', price: 140, times: ['17:00'], cap: 20 },
      { id: 'A4', name: 'Island hopping day tour', dept: 'Tours', price: 210, times: ['08:00'], cap: 14 },
      { id: 'A5', name: 'Kids club half day', dept: 'Kids club', price: 45, times: ['09:00', '14:00'], cap: 15 },
      { id: 'A6', name: 'Private beach dinner', dept: 'Food & beverage', price: 380, times: ['19:00'], cap: 3 },
      { id: 'A7', name: 'Sunrise yoga', dept: 'Wellness', price: 0, times: ['06:30'], cap: 18 },
      { id: 'A8', name: 'Kayak & paddleboard hire', dept: 'Water sports', price: 35, times: ['09:00', '11:00', '15:00'], cap: 10 }
    ];
    const inhouse = reservations.filter(r => r.status === 'inhouse');
    const actBookings = [];
    for (let i = 0; i < 26; i++) {
      const a = pick(activities), r = pick(inhouse);
      actBookings.push({ id: 'AB' + (500 + i), actId: a.id, resId: r.id, date: addDays(TODAY, int(0, 2)), time: pick(a.times), people: int(1, 2), status: 'confirmed' });
    }

    const menu = [
      { id: 'M1', cat: 'Breakfast', name: 'Tropical fruit bowl', price: 18 },
      { id: 'M2', cat: 'Breakfast', name: 'Eggs Benedict', price: 26 },
      { id: 'M3', cat: 'Mains', name: 'Grilled barramundi', price: 42 },
      { id: 'M4', cat: 'Mains', name: 'Wagyu burger', price: 34 },
      { id: 'M5', cat: 'Mains', name: 'Coconut prawn curry', price: 38 },
      { id: 'M6', cat: 'Mains', name: 'Garden risotto (v)', price: 30 },
      { id: 'M7', cat: 'Starters', name: 'Kingfish ceviche', price: 24 },
      { id: 'M8', cat: 'Starters', name: 'Salt & pepper squid', price: 22 },
      { id: 'M9', cat: 'Drinks', name: 'Mango daiquiri', price: 21 },
      { id: 'M10', cat: 'Drinks', name: 'Local craft lager', price: 12 },
      { id: 'M11', cat: 'Drinks', name: 'Glass of sauvignon blanc', price: 15 },
      { id: 'M12', cat: 'Drinks', name: 'Fresh coconut', price: 9 },
      { id: 'M13', cat: 'Desserts', name: 'Pandan panna cotta', price: 16 },
      { id: 'M14', cat: 'Desserts', name: 'Passionfruit pavlova', price: 16 }
    ];
    const outlets = ['Lagoon Restaurant', 'Driftwood Pool Bar', 'In-room dining'];

    const tickets = [
      { id: 'T301', room: '207', title: 'Air-con not cooling', priority: 'urgent', status: 'waiting', by: 'Front desk', assignee: 'S9', created: addDays(TODAY, -2), blocks: true },
      { id: 'T302', room: 'V4', title: 'Outdoor shower low pressure', priority: 'medium', status: 'open', by: 'Housekeeping', assignee: 'S9', created: addDays(TODAY, -1), blocks: false },
      { id: 'T303', room: '112', title: 'TV remote missing', priority: 'low', status: 'open', by: 'Guest app', assignee: null, created: TODAY, blocks: false },
      { id: 'T304', room: 'Pool area', title: 'Pool pump noisy at night', priority: 'high', status: 'in_progress', by: 'Night audit', assignee: 'S9', created: addDays(TODAY, -3), blocks: false },
      { id: 'T305', room: '304', title: 'Bathroom door handle loose', priority: 'medium', status: 'done', by: 'Housekeeping', assignee: 'S9', created: addDays(TODAY, -4), blocks: false }
    ];

    const pick2 = () => pick(inhouse);
    const requests = [
      { id: 'Q1', resId: pick2().id, text: 'Extra towels and 2 pillows', dept: 'Housekeeping', status: 'new', at: '09:12' },
      { id: 'Q2', resId: pick2().id, text: 'Late checkout until 2 pm?', dept: 'Front office', status: 'new', at: '09:40' },
      { id: 'Q3', resId: pick2().id, text: 'Baby cot for tonight', dept: 'Housekeeping', status: 'in_progress', at: '08:05' },
      { id: 'Q4', resId: pick2().id, text: 'Airport transfer Friday 7 am', dept: 'Front office', status: 'done', at: '07:30' }
    ];

    const channelStatus = [
      { name: 'Direct website', commission: 0, synced: 'Just now', ok: true },
      { name: 'Booking.com', commission: 15, synced: '2 min ago', ok: true },
      { name: 'Expedia', commission: 18, synced: '2 min ago', ok: true },
      { name: 'Airbnb', commission: 14, synced: '41 min ago', ok: false },
      { name: 'Phone / email', commission: 0, synced: 'Manual', ok: true },
      { name: 'Walk-in', commission: 0, synced: 'Manual', ok: true }
    ];

    return { roomTypes, zones, rooms, guests, reservations, staff, roster, activities, actBookings, menu, outlets, tickets, requests, channelStatus, orders: [], seq: 9000, guestResId: inhouse[0].id };
  };
})();
